package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.time.StopWatch#stop()
 */
public class StopWatch_stop_TriageGen1Test {







    @Test(expected = IllegalStateException.class)
    public void testStop_WhenAlreadyStopped_ShouldThrowIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.stop();

        // Second stop should throw exception as state is now STATE_STOPPED
        stopWatch.stop();
    }


}

package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.time.StopWatch#stop()
 */
public class StopWatch_stop_TriageGen1Test {









    @Test
    public void testStop_AfterReset_ShouldThrowIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.reset();

        try {
            stopWatch.stop();
            fail("Expected IllegalStateException to be thrown");
        } catch (IllegalStateException e) {
            assertEquals("Stopwatch is not running. ", e.getMessage());
        }
    }
}
